$st = db()->prepare(
  'INSERT IGNORE INTO sales (email_id,channel,kind,ticket_no,route,segment,depart_at,amount,passenger,occurred_at,subject,snippet)
   VALUES (:email_id,:channel,:kind,:ticket_no,:route,:segment,:depart_at,:amount,:passenger,:occurred_at,:subject,:snippet)'
);
$ins = 0;
foreach ($rows as [$from, $subj, $body, $at, $eid]) {
    $r = SalesParser::parse($from, $subj, $body, $at, $eid);
    $st->execute($r);
    $ins += $st->rowCount();
}
